{
  "done": false,
  "tool": "manage_backends",
  "args": {
    "operation": "add",
    "name": "Surveillance Data",
    "url": "http://localhost:7807",
    "widgets_json": {
      "case_notes": {
        "name": "Case Notes",
        "description": "Notes for one surveillance case.",
        "endpoint": "/case-notes",
        "type": "markdown",
        "gridData": {
          "w": 12,
          "h": 8
        },
        "params": [
          {
            "paramName": "case_id",
            "type": "text",
            "label": "Case",
            "value": "C-1042",
            "description": "Case identifier."
          },
          {
            "paramName": "case_scope",
            "type": "text",
            "label": "Case scope",
            "value": "C-1042",
            "description": "Case bundle reviewed across the room."
          }
        ]
      },
      "policy_pdf": {
        "name": "Policy Digest",
        "description": "Latest surveillance policy digest.",
        "endpoint": "/policy-digest",
        "type": "pdf",
        "gridData": {
          "w": 16,
          "h": 14
        },
        "params": [
          {
            "paramName": "case_scope",
            "type": "text",
            "label": "Case scope",
            "value": "C-1042",
            "description": "Case bundle reviewed across the room."
          }
        ]
      }
    },
    "apps_json": [
      {
        "name": "Case Research Room",
        "description": "Case notes and policy digest.",
        "tabs": {
          "notes": {
            "id": "notes",
            "name": "Notes",
            "layout": [
              {
                "i": "case_notes",
                "x": 0,
                "y": 0,
                "w": 12,
                "h": 8
              }
            ]
          },
          "policy": {
            "id": "policy",
            "name": "Policy",
            "layout": [
              {
                "i": "policy_pdf",
                "x": 0,
                "y": 0,
                "w": 16,
                "h": 14
              }
            ]
          }
        },
        "groups": [
          {
            "name": "Case Sync",
            "type": "param",
            "paramName": "case_scope",
            "widgetIds": [
              "case_notes",
              "policy_pdf"
            ]
          }
        ]
      }
    ]
  }
}
